<?php
require __DIR__ . '/../../includes/bootstrap.php';
$u = requireRole('employee', true);
if ($_SERVER['REQUEST_METHOD'] !== 'POST') jsonOut(['error' => 'POST required'], 405);
csrfCheck(true);
if (activeBreakFor((int)$u['employee_id'])) jsonOut(['error' => 'You already have an active break.'], 409);
try {
    // Start time is generated by the database server (UTC), never by the browser.
    db()->prepare("INSERT INTO break_records (employee_id, start_utc) VALUES (?, UTC_TIMESTAMP())")->execute([$u['employee_id']]);
} catch (PDOException $ex) {
    if ($ex->getCode() === '23000') jsonOut(['error' => 'You already have an active break.'], 409); // unique index safety net
    throw $ex;
}
jsonOut(['ok' => true]);
